package config

import (
	"fmt"
	"os"

	"go.yaml.in/yaml/v4"
)

/*
# This file is automatically generated by Verde.
# To see more information about `verde_config` and how it can be used, go to {INSERT URL HERE WHEN DOCS ARE MADE}
version: 0
name: verde-game
serve:
  address: 127.0.0.1 # or localhost or 0.0.0.0
  port: 45678
  placeIds: [1234567890]
sync:
  - instance: ReplicatedStorage
    path: src/shared
  - instance: ServerScriptService
    path: src/server
  - instance: StarterPlayer/StarterPlayerScripts
    path: src/local
  - instance: StarterGui
    path: src/gui
  - instance: Workspace
    path: src/workspace
  - instance: ReplicatedFirst
    path: src/first
  - instance: ServerStorage
    path: src/storage
  - instance: Lighting
    path: src/lighting
ignore:
  paths: ["**\/*.tmp", "**\/.DS_Store"]
instances: ["Workspace/Camera", "Workspace/Terrain"]

conflicts:
onConnect: disk # disk | studio | interactive
*/

type OnConnect string

const (
	OnConnectDisk        OnConnect = "disk"
	OnConnectStudio      OnConnect = "studio"
	OnConnectInteractive OnConnect = "interactive"
)

type SyncInstance struct {
	Instance string `yaml:"instance"`
	Path     string `yaml:"path"`
}

type Cfg struct {
	Version int    `yaml:"version"`
	Name    string `yaml:"name"`
	Serve   struct {
		Address  string `yaml:"address"`
		Port     int    `yaml:"port"`
		PlaceIds []int  `yaml:"placeIds"`
	} `yaml:"serve"`
	Sync   []SyncInstance `yaml:"sync"`
	Ignore struct {
		Paths     []string `yaml:"paths"`
		Instances []string `yaml:"instances"`
		Classes   []string `yaml:"classes"`
	}
	Conflicts struct {
		OnConnect OnConnect `yaml:"onConnect"`
	} `yaml:"conflicts"`
}

func Load(path string) (*Cfg, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	var cfg Cfg
	dec := yaml.NewDecoder(file)
	dec.KnownFields(true)
	if err := dec.Decode(&cfg); err != nil {
		return nil, fmt.Errorf("parse %s: %w", path, err)
	}
	return &cfg, nil
}
